import{_ as a,o as s,c as i,a0 as t}from"./chunks/framework.jwovEGr5.js";const u=JSON.parse('{"title":"tfire: C로 터미널 불멍 만들기","description":"","frontmatter":{},"headers":[],"relativePath":"outta-space/project/tfire-터미널-불멍-만들기.md","filePath":"outta-space/project/tfire-터미널-불멍-만들기.md"}'),o={name:"outta-space/project/tfire-터미널-불멍-만들기.md"};function n(d,e,p,l,c,r){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="tfire-c로-터미널-불멍-만들기" tabindex="-1">tfire: C로 터미널 불멍 만들기 <a class="header-anchor" href="#tfire-c로-터미널-불멍-만들기" aria-label="Permalink to &quot;tfire: C로 터미널 불멍 만들기&quot;">​</a></h1><p>터미널에서 모닥불 GIF를 아스키 아트로 재생하는 작은 프로그램 <code>tfire</code>를 만들었다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tfire</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> red</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tfire</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> green</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tfire</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blue</span></span></code></pre></div><p>처음에는 GIF를 문자로 바꾸어 출력하면 끝날 것 같았다. 실제로 만들어보니 명령행 인자, 이미지의 메모리 구조, 터미널 제어, 애니메이션 시간 처리와 빌드까지 여러 개념이 연결된 프로젝트였다.</p><h2 id="문자열과-enum-연결하기" tabindex="-1">문자열과 enum 연결하기 <a class="header-anchor" href="#문자열과-enum-연결하기" aria-label="Permalink to &quot;문자열과 enum 연결하기&quot;">​</a></h2><p>C의 <code>enum</code>에는 <code>&quot;red&quot;</code> 같은 문자열을 직접 저장할 수 없다. 따라서 사용자가 입력한 문자열을 <code>strcmp()</code>로 비교해 프로그램 내부의 enum 값으로 바꾸었다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;red&quot; → COLOR_RED → ANSI 빨간색 코드</span></span></code></pre></div><p>문자열을 가리키는 포인터에는 <code>const char *</code>를 사용했다. 입력값과 문자열 리터럴을 수정하지 않겠다는 의도를 타입으로 나타낼 수 있었다. 잘못된 색상이 들어오면 <code>stderr</code>에 오류를 출력하고 0이 아닌 종료 상태를 반환했다.</p><h2 id="픽셀을-아스키-문자로-바꾸기" tabindex="-1">픽셀을 아스키 문자로 바꾸기 <a class="header-anchor" href="#픽셀을-아스키-문자로-바꾸기" aria-label="Permalink to &quot;픽셀을 아스키 문자로 바꾸기&quot;">​</a></h2><p><code>stb_image</code>로 이미지를 RGB 형식으로 읽으면 픽셀들은 1차원 바이트 배열에 연속해서 저장된다. <code>(x, y)</code> 위치의 픽셀은 다음 관계로 찾을 수 있다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pixel index = (y × image width + x) × 3</span></span></code></pre></div><p>여기서 연속된 세 바이트가 각각 red, green, blue다. RGB를 문자 하나로 바꾸기 위해 사람의 눈이 초록색 밝기에 더 민감하다는 점을 반영한 정수식을 사용했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brightness = (red × 21 + green × 72 + blue × 7) / 100</span></span></code></pre></div><p>0부터 255까지의 밝기는 어두운 문자부터 밝은 문자까지 배치한 문자열의 인덱스로 변환했다.</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot; .:-=+*#</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">@&quot;</span></span></code></pre></div><p>이미지를 줄일 때는 출력 좌표를 원본 좌표에 대응시키는 가장 단순한 nearest-neighbor 방식을 사용했다. 터미널 문자는 정사각형이 아니라 세로로 긴 편이어서 출력 높이를 약 절반으로 보정해야 원본 비율과 비슷하게 보였다.</p><h2 id="터미널-크기에-맞추기" tabindex="-1">터미널 크기에 맞추기 <a class="header-anchor" href="#터미널-크기에-맞추기" aria-label="Permalink to &quot;터미널 크기에 맞추기&quot;">​</a></h2><p><code>ioctl()</code>의 <code>TIOCGWINSZ</code> 요청으로 현재 터미널의 열과 행을 함께 읽었다.</p><ul><li><code>ws_col</code>: 터미널 너비</li><li><code>ws_row</code>: 터미널 높이</li></ul><p>먼저 터미널 너비에 맞춰 출력 크기를 계산하고, 계산된 높이가 화면을 넘으면 높이를 기준으로 너비를 다시 계산했다. 덕분에 창 크기가 달라도 불꽃 전체가 화면 안에 들어온다.</p><p>애니메이션 중에는 ANSI escape sequence로 커서를 왼쪽 위로 이동해 같은 위치에 다음 프레임을 덮어썼다. 매번 화면 전체를 지우는 대신 남은 영역만 정리해서 깜빡임을 줄였다. <code>printf()</code>의 출력이 버퍼에 남지 않도록 프레임마다 <code>fflush(stdout)</code>도 호출했다.</p><h2 id="gif는-프레임-배열이다" tabindex="-1">GIF는 프레임 배열이다 <a class="header-anchor" href="#gif는-프레임-배열이다" aria-label="Permalink to &quot;GIF는 프레임 배열이다&quot;">​</a></h2><p>정지 이미지는 <code>stbi_load()</code>로 바로 읽을 수 있지만, GIF 전체를 재생하려면 파일을 먼저 메모리에 읽고 <code>stbi_load_gif_from_memory()</code>에 전달해야 했다.</p><p>파일을 메모리에 읽는 과정에서 다음 표준 C 파일 함수를 사용했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fopen → fseek → ftell → rewind → malloc → fread → fclose</span></span></code></pre></div><p>디코딩된 프레임들은 하나의 큰 메모리 배열에 연속해서 들어 있다. 한 프레임의 크기를 구하면 <code>i</code>번째 프레임의 시작 위치를 계산할 수 있다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frame size = width × height × 3</span></span>
<span class="line"><span>frame i = frames + i × frame size</span></span></code></pre></div><p>이 과정에서 포인터의 소유권도 중요하게 배웠다. <code>frame</code>은 <code>frames</code> 내부를 가리키는 포인터일 뿐 별도로 할당된 메모리가 아니다. 처음에는 <code>frame</code>을 해제해 <code>invalid pointer</code> 오류가 발생했다. 실제로 해제해야 하는 것은 할당된 배열의 시작 주소인 <code>frames</code>였다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gif_data → 직접 malloc했으므로 free()</span></span>
<span class="line"><span>frames, delays → stb_image가 할당했으므로 stbi_image_free()</span></span>
<span class="line"><span>frame → frames 내부를 가리킬 뿐이므로 해제하지 않음</span></span></code></pre></div><p>각 프레임은 GIF에 기록된 delay만큼 <code>nanosleep()</code>으로 기다린 뒤 다음 프레임으로 넘어간다. <code>Ctrl-C</code>를 받으면 반복문을 끝내고 ANSI 색상, 커서와 원래 터미널 화면을 복원하도록 신호 처리도 추가했다.</p><h2 id="빌드하며-알게-된-점" tabindex="-1">빌드하며 알게 된 점 <a class="header-anchor" href="#빌드하며-알게-된-점" aria-label="Permalink to &quot;빌드하며 알게 된 점&quot;">​</a></h2><p><code>stb_image</code> 내부에서 <code>pow()</code>를 사용하기 때문에 헤더를 포함하는 것만으로는 빌드가 끝나지 않았다. 링크 단계에서 <code>undefined reference to pow</code>가 발생했고, Makefile의 링크 명령 뒤에 수학 라이브러리 <code>-lm</code>을 추가해 해결했다.</p><p>기본 GIF는 GNU <code>ld</code>로 바이너리 오브젝트로 변환해 실행 파일 안에 포함했다. 그래서 설치 후 이미지 파일의 위치와 관계없이 <code>tfire red</code>만으로 실행할 수 있다. 마지막에는 <code>make install</code> 규칙을 만들고 사용자 명령 경로인 <code>~/.local/bin</code>에 설치했다.</p><h2 id="마무리" tabindex="-1">마무리 <a class="header-anchor" href="#마무리" aria-label="Permalink to &quot;마무리&quot;">​</a></h2><p>작은 불멍 프로그램이지만 C 프로그램의 여러 층을 한 번에 경험할 수 있었다.</p><ul><li>문자열 입력을 enum으로 변환하는 방법</li><li>1차원 픽셀 배열과 포인터 연산</li><li>메모리를 할당한 주체에 따른 올바른 해제</li><li><code>ioctl()</code>과 ANSI escape sequence를 이용한 터미널 제어</li><li>프레임 시간, 출력 버퍼와 신호 처리</li><li>컴파일과 링크의 차이, Makefile을 통한 빌드와 설치</li></ul><p>특히 “어떤 포인터가 메모리를 소유하는가”와 “컴파일 성공과 링크 성공은 다르다”는 점이 기억에 남았다. 화면에 불꽃이 움직이는 결과가 바로 보여서 C의 낮은 수준의 개념들을 비교적 즐겁게 확인할 수 있었던 프로젝트였다.</p>`,37)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
